import pygame

from tetris import Tetris, COLS, ROWS, COLORS

CELL = 30
PANEL = 190
W, H = COLS * CELL + PANEL, ROWS * CELL
WHITE = (240, 240, 240)
GREY = (130, 130, 140)


def run():
    pygame.init()
    screen = pygame.display.set_mode((W, H))
    pygame.display.set_caption("Tetris")
    font = pygame.font.SysFont("arial", 20)
    big = pygame.font.SysFont("arial", 34, bold=True)
    clock = pygame.time.Clock()
    game = Tetris()
    fall = 0.0
    running = True
    while running:
        dt = clock.tick(60) / 1000.0
        for e in pygame.event.get():
            if e.type == pygame.QUIT:
                running = False
            elif e.type == pygame.KEYDOWN:
                if e.key == pygame.K_ESCAPE:
                    running = False
                elif e.key == pygame.K_r:
                    game.reset()
                    fall = 0.0
                elif e.key == pygame.K_p:
                    game.paused = not game.paused
                elif game.game_over or game.paused:
                    pass
                elif e.key == pygame.K_LEFT:
                    game.move(-1)
                elif e.key == pygame.K_RIGHT:
                    game.move(1)
                elif e.key == pygame.K_DOWN:
                    if game.move(0, 1):
                        game.score += 1
                    fall = 0.0
                elif e.key == pygame.K_UP:
                    game.rotate_piece()
                elif e.key == pygame.K_SPACE:
                    game.hard_drop()
                    fall = 0.0
        if not game.game_over and not game.paused:
            fall += dt
            if fall >= game.drop_interval():
                fall = 0.0
                game.step()
        draw(screen, game, font, big)
        pygame.display.flip()
    pygame.quit()


def draw(screen, game, font, big):
    screen.fill((15, 15, 25))
    bw = COLS * CELL
    for y in range(ROWS):
        for x in range(COLS):
            k = game.board[y][x]
            rect = pygame.Rect(x * CELL + 1, y * CELL + 1, CELL - 2, CELL - 2)
            pygame.draw.rect(screen, COLORS[k] if k else (26, 26, 38), rect, border_radius=3)
    for x, y in game.piece.cells():
        if y >= 0:
            pygame.draw.rect(screen, COLORS[game.piece.kind],
                             (x * CELL + 1, y * CELL + 1, CELL - 2, CELL - 2), border_radius=3)
    pygame.draw.rect(screen, GREY, (0, 0, bw, ROWS * CELL), 2)

    px = bw + 16
    for i, (label, val) in enumerate((("Score", game.score), ("Lines", game.lines), ("Level", game.level))):
        screen.blit(font.render(f"{label}: {val}", True, WHITE), (px, 20 + i * 30))
    screen.blit(font.render("Next:", True, WHITE), (px, 120))
    shape = game.next_piece.shape
    size = 22
    ox = px + (PANEL - 32 - len(shape[0]) * size) // 2
    oy = 150
    for cy, row in enumerate(shape):
        for cx, v in enumerate(row):
            if v:
                pygame.draw.rect(screen, COLORS[game.next_piece.kind],
                                 (ox + cx * size, oy + cy * size, size - 2, size - 2), border_radius=3)
    help_y = 260
    for line in ("Left/Right: move", "Down: soft drop", "Up: rotate", "Space: hard drop",
                 "P: pause", "R: restart", "Esc: quit"):
        screen.blit(font.render(line, True, GREY), (px, help_y))
        help_y += 26
    if game.paused:
        overlay(screen, big, "PAUSED")
    if game.game_over:
        overlay(screen, big, "GAME OVER")


def overlay(screen, big, text):
    s = pygame.Surface((COLS * CELL, ROWS * CELL), pygame.SRCALPHA)
    s.fill((0, 0, 0, 170))
    screen.blit(s, (0, 0))
    t = big.render(text, True, (255, 80, 80))
    screen.blit(t, t.get_rect(center=(COLS * CELL // 2, ROWS * CELL // 2)))
